}

public class DAYSINPRIORYEARS {
/**
     * Return the number of days in prior years since 1900
     *
     * @return    days  number of days in years prior to yr.
     * @param     yr    a year (1900 < yr < 4000)
     * @exception IllegalArgumentException if year is outside of range.
     */

    private static int daysInPriorYears(int yr)
    {
        if (yr < 1900) {
            throw new IllegalArgumentException(
                "'year' must be 1900 or greater");
        }

        int yr1  = yr - 1;
        int leapDays =   yr1 / 4   // plus julian leap days in prior years
                       - yr1 / 100 // minus prior century years
                       + yr1 / 400 // plus years divisible by 400 
                       - 460;      // leap days in previous 1900 years

        return 365 * (yr - 1900) + leapDays;
    }
}

public class DECODENUMBER {
/**
     * Do the dirty work of decoding; made a private static method to
     * facilitate testing the algorithm
     */

    public static double decodeNumber(int number)
    {
        long raw_number = number;

        // mask off the two low-order bits, 'cause they're not part of
        // the number
        raw_number = raw_number >> 2;
        double rvalue = 0;

        if ((number & 0x02) == 0x02)
        {
            // ok, it's just a plain ol' int; we can handle this
            // trivially by casting
            rvalue = ( double ) (raw_number);
        }
        else
        {

            // also trivial, but not as obvious ... left shift the
            // bits high and use that clever static method in Double
            // to convert the resulting bit image to a double
            rvalue = Double.longBitsToDouble(raw_number << 34);
        }
        if ((number & 0x01) == 0x01)
        {

            // low-order bit says divide by 100, and so we do. Why?
            // 'cause that's what the algorithm says. Can't fight city
            // hall, especially if it's the city of Redmond
            rvalue /= 100;
        }

        return rvalue;
    }
}

public class USESAN {
/**
   * tests if this word should have an "a" or an "an"
   * before it. char c is the first character of the word.
   */
  public static boolean usesAn(char c) {
    boolean result = false;
    switch(c) {
      case 'a':
      case 'A':
      case 'e':
      case 'E':
      case 'i':
      case 'I':
      case 'o':
      case 'O':
      case 'h':
      case 'H':
        result = true;
        break;
      default:
        result = false;
        break;
    }
    return result;
  }
}

public class DIGITS {
/** Computes the given value's number of digits. */
  private static int digits(int value) {
    int digits = 0;
    while (value > 0) {
      value /= 10;
      digits++;
    }
    return digits;
  }
}

public class NUMINSERIES {
/** returns the number of of elements in a series given from, to, and by values */
  private int numInSeries(int from, int to, int by)
  {
    if (by < 1)
      throw new IllegalArgumentException("numInSeries passed a stepBy value < 1");

    // could calc this but simple loop suffices for our purposes
    int count = 0;
    for (int i = from; i <= to; i += by)
        count++;
    return count;
  }
}

public class EFFECTIVEC {
/** calculate the effective size C of an image given various params */
  private int effectiveC(int sizeC, int rgb, int lutLen, boolean indexed, boolean falseColor)
  {
    int effC = sizeC;

    if (indexed)  // this is from Melissa
    {
      if (falseColor)
        effC /= rgb;
      else // not falseColor
        effC *= lutLen;
    }

    return effC;
  }
}

public class GETBYTESPERPIXEL {
/**
   * Retrieves how many bytes per pixel the current plane or section has.
   * @return the number of bytes per pixel.
   */
  public static int getBytesPerPixel(int type) {
    switch(type) {
    case 0:
    case 1:
      return 1;  // INT8 or UINT8
    case 2:
    case 3:
      return 2;  // INT16 or UINT16
    case 4:
    case 5:
    case 6:
      return 4;  // INT32, UINT32 or FLOAT
    case 7:
      return 8;  // DOUBLE
    }
    throw new RuntimeException("Unknown type with id: '" + type + "'");
  }
}

public class GETMILLISFROMTICKS {
/**
   * Converts from two-word tick representation to milliseconds.
   * Mainly useful in conjunction with COBOL date conversion.
   */
  public static long getMillisFromTicks(long hi, long lo) {
    long ticks = ((hi << 32) | lo);
    return ticks / 10000; // 100 ns = 0.0001 ms
  }
}

public class CANFITINMEMORY {
/** Returns true if a byte buffer of the given size will fit in memory. */
  public static boolean canFitInMemory(long bufferSize) {
    Runtime r = Runtime.getRuntime();
    long mem = r.freeMemory() / 2;
    return bufferSize < mem && bufferSize <= Integer.MAX_VALUE;
  }
}

public class CHECKDOUBLEPRECISE {
/**
	 * Checks a double value is double precise. If value is 2.1, then return
	 * true; if value is 2.1000000001 or 2.099999999999, then return false.
	 * 
	 * @param dValue
	 * @return if precise
	 */
	public static boolean checkDoublePrecise( double dValue )
	{
		if ( dValue - (int) dValue == 0 )
		{
			return true;
		}
		String sValue = String.valueOf( dValue );
		if ( sValue.length( ) < 8 )
		{
			return true;
		}
		int iPoint = sValue.indexOf( '.' );
		int iZero = sValue.lastIndexOf( "00000000" ); //$NON-NLS-1$
		if ( iZero >= iPoint )
		{
			return false;
		}
		int iNine = sValue.lastIndexOf( "99999999" ); //$NON-NLS-1$
		if ( iNine >= iPoint )
		{
			return false;
		}
		return true;
	}
}

public class ISVALIDPROCEEDING {
/**
	 * Test whether the char immediately before the candidate "row" key is
	 * valid.
	 * 
	 * @param operator
	 * @return
	 */
	private static boolean isValidProceeding( char operator )
	{
		if ( ( operator >= 'A' && operator <= 'Z' )
				|| ( operator >= 'a' && operator <= 'z' ) || operator == '_' )
			return false;

		return true;
	}
}

public class PERCENT {
/**
	 * @param denom
	 *            the denominator
	 * @param num
	 *            the numerator
	 * @param valueIfZero
	 * 			  The percent value to return if the numerator is zero. The default is null.
	 * @return the percentage of two numbers
	 */
	static double percent(double denom, double num, double valueIfZero)
	{
		if(num == 0d)
		{
			return valueIfZero;
		}
		if(denom == 0d)
		{
			throw ( new IllegalArgumentException(
					"There exists illegal parameter:" + denom) );
		}

		return ( num / denom ) * 100;
	}
}

public class ISWITHININTERVAL {
/**
	 * Determin whether two values are in speficied interval. Please notice,
	 * such a calculation approach only applies to asc order. If desc order
	 * needs to be used too, the intervalValue must be conversed in the start.
	 * 
	 * @param startValue
	 * @param intervalValue
	 * @param currValue
	 * @param prevValue
	 * @return true in interval
	 */
	static boolean isWithinInterval( double startValue, double intervalValue,
			double currValue, double prevValue )
	{
		assert intervalValue != 0;

		boolean isSame = false;
		double curr = ( currValue - startValue ) / intervalValue;
		double prev = ( prevValue - startValue ) / intervalValue;

		// When there is a start value, all the
		// values that less than that start value would enter
		// one group
		if ( curr < 0 && prev < 0 )
			return true;

		if ( curr < 0 || prev < 0 )
			return false;

		int currDiv = (int) ( curr );
		int prevDiv = (int) ( prev );
		if ( currDiv == prevDiv )
		{
			isSame = true;
		}
		return isSame;
	}
}

