	}
}

public class PERCENT {
/**
	 * @param denom
	 *            is the denominator
	 * @param num
	 *            is the numerator
	 * @return the percentage of two numbers
	 */
	public static double percent( double denom, double num )
	{

		if ( num == 0 )
			return 0;
		assert ( denom != 0d );
		return ( num / denom ) * 100;
	}
}

