public class ADJUSTPOSITION {
/**
	 * Adjusts position of destination index. The range is from zero to count-1.
	 * 
	 * @param destIndex
	 *            index of destination
	 * @param count
	 *            count of row.
	 * @return position after adjusting.
	 */

	protected int adjustPosition( int destIndex, int count )
	{
		if ( destIndex < 0 )
			destIndex = 0;
		if ( destIndex > count - 1 )
			destIndex = count - 1;
		return destIndex;
	}
}

public class FORMRGB {
/**
	 * Calculates the integer color value given its red, blue, green values. If
	 * any color factor is over 0xFF, it will be clipped to 0xFF; if any color
	 * factor is below 0, it will be increased to 0.
	 * 
	 * 
	 * @param r
	 *            red value.
	 * @param g
	 *            green value.
	 * @param b
	 *            blue value.
	 * @return the integer color value of the given color factors.
	 */

	public static int formRGB( int r, int g, int b )
	{
		// clip to 0 ~ 0xFF

		r = r > 0xFF ? 0xFF : r < 0 ? 0 : r;
		g = g > 0xFF ? 0xFF : g < 0 ? 0 : g;
		b = b > 0xFF ? 0xFF : b < 0 ? 0 : b;

		return ( r << 16 ) + ( g << 8 ) + b;
	}
}

