public class GETGAP {
/**
	 * Calculate gap to avoid cross-line when drawing thick/double line.
	 */
	private static int getGap( int x, int y, int i )
	{
		if ( x == 0 )
		{
			return 0;
		}

		if ( i < 0 )
		{
			i = 0;
		}

		if ( i > x )
		{
			i = x;
		}

		return  y * i / x ;
	}
}

public class BLEND {
/**
	 * Blends two primary color components based on the provided ratio.
	 * 
	 * @param v1
	 *            first component
	 * @param v2
	 *            second component
	 * @param ratio
	 *            percentage of the first component in the blend
	 * @return
	 */
	private static int blend( int v1, int v2, int ratio )
	{
		int b = ( ratio * v1 + ( 100 - ratio ) * v2 ) / 100;
		return Math.min( 255, b );
	}
}

public class ISPOPBLOCK {
/**
     * Checks if a given blockID is a known pop block
     * @param blockID
     * @return true if blockID is known pop block
     */
    private boolean isPopBlock(int blockID) {
        return blockID == 6 || blockID == 26 || blockID == 27 || blockID == 28 || blockID == 37 || blockID == 38 || blockID == 39 ||
                blockID == 40 || blockID == 50 || blockID == 55 || blockID == 59 || blockID == 64 || blockID == 65 || blockID == 66 ||
                blockID == 69 || blockID == 71 || blockID == 75 || blockID == 76 || blockID == 77 || blockID == 81 || blockID == 83 ||
                blockID == 93 || blockID == 94 || blockID == 31 || blockID == 32 || blockID == 96 || blockID == 111 || blockID == 115;
    }
}

public class CHECKSUMPUSHBYTE {
/** CRC check taken from Zephyr PDF's */
	public static int ChecksumPushByte(int currentChecksum, int newByte) {

		currentChecksum = (currentChecksum ^ newByte);

		for (int bit = 0; bit < 8; bit++) {

			if ((currentChecksum & 1) == 1)
				currentChecksum = ((currentChecksum >> 1) ^ 0x8C);

			else
				currentChecksum = (currentChecksum >> 1);
		}

		return currentChecksum;
	}
}

public class CONVERTTEMPO {
