public class GCD {
/**
   * Determines the greatest common divisor (GCD) of two integers.
   * 
   *  @param m the first integer
   *  @param n the second integer
   *  
   *  @return the greatest common divisor of m and n
   */
  public static int gcd(int m, int n) {
    if (m == 0 && n == 0)
      return 0;
    if (m < n) {
      int t = m;
      m = n;
      n = t;
    }
    int r = m % n;
    if (r == 0) {
      return n;
    } else {
      return gcd(n, r);
    }
  }
}

public class NEXTRAND {
/** Marsaglia, 2003. */
  long nextRand(long x) {
    x ^= (x << 13);
    x ^= (x >>> 7);
    return (x ^= (x << 17));
  }
}

public class GETVINTSIZE {
/**
   * Get the encoded length if an integer is stored in a variable-length format
   * @return the encoded length 
   */
  public static int getVIntSize(long i) {
    if (i >= -112 && i <= 127) {
      return 1;
    }

    if (i < 0) {
      i ^= -1L; // take one's complement'
    }
    // find the number of bytes with non-leading zeros
    int dataBits = Long.SIZE - Long.numberOfLeadingZeros(i);
    // find the number of data bytes + length byte
    return (dataBits + 7) / 8 + 1;
  }
}

public class GETMAXDEPTH {
/**
   * Deepest recursion before giving up and doing a heapsort.
   * Returns 2 * ceil(log(n)).
   */
  protected static int getMaxDepth(int x) {
    if (x <= 0)
      throw new IllegalArgumentException("Undefined for " + x);
    return (32 - Integer.numberOfLeadingZeros(x - 1)) << 2;
  }
}

public class GETPASSFACTOR {
/**
     * Determine the number of segments to merge in a given pass. Assuming more
     * than factor segments, the first pass should attempt to bring the total
     * number of segments - 1 to be divisible by the factor - 1 (each pass
     * takes X segments and produces 1) to minimize the number of merges.
     */
    private int getPassFactor(int factor, int passNo, int numSegments) {
      if (passNo > 1 || numSegments <= factor || factor == 1) 
        return factor;
      int mod = (numSegments - 1) % (factor - 1);
      if (mod == 0)
        return factor;
      return mod + 1;
    }
}

public class GETCLOSESTPOWEROF2 {
/**
   * Return the exponent of the power of two closest to the given
   * positive value, or zero if value leq 0.
   * This follows the observation that the msb of a given value is
   * also the closest power of two, unless the bit following it is
   * set.
   */
  private static int getClosestPowerOf2(int value) {
    if (value <= 0)
      throw new IllegalArgumentException("Undefined for " + value);
    final int hob = Integer.highestOneBit(value);
    return Integer.numberOfTrailingZeros(hob) +
      (((hob >>> 1) & value) == 0 ? 0 : 1);
  }
}

public class NUMBERDIGITS {
/**
   * Calculate how many digits are in the 10-based integer.
   * 
   * @param value
   * @return
   */
  private static int numberDigits(int value) {
    int digits = 0;
    while ((value = value / 10) > 0) {
      digits++;
    }
    return digits;
  }
}

public class WITHINTOLERANCE {
/**
     * Calculate if the error in expected and observed values is within tolerance
     *
     * @param expectedValue  expected value of experiment
     * @param observedValue  observed value of experiment
     * @param tolerance      per cent tolerance for error, represented as a int
     */
    private boolean withinTolerance(long expectedValue,
                                    long observedValue,
                                    int tolerance) {
        double diff = 1.0 * Math.abs(observedValue - expectedValue);
        double thrs = expectedValue * (tolerance/100);
        return diff > thrs;
    }
}

public class SETVALUERANGE {
/**
   * Forces the value passed in to be between the range passed in
   *
   * @param val the value to constrain
   * @param min the minimum acceptable value
   * @param max the maximum acceptable value
   * @return the constrained value
   */
  private int setValueRange(int val, int min, int max)
  {
    val = Math.max(val, min);
    val = Math.min(val, max);
    return val;
  }
}

public class GETDOUBLE {
/**
   * Converts excel's internal RK format into a double value
   *
   * @param rk the rk number in bits
   * @return the double representation
   */
  public static double getDouble(int rk)
  {
    if ((rk & 0x02) != 0)
    {
      int intval = rk >> 2;

      double value = intval;
      if ((rk & 0x01) != 0)
      {
        value /= 100;
      }

      return value;
    }
    else
    {
      long valbits = (rk & 0xfffffffc);
      valbits <<= 32;
      double value = Double.longBitsToDouble(valbits);

      if ((rk & 0x01) != 0)
      {
        value /= 100;
      }

      return value;
    }
  }
}

public class ROTLEFT15BIT {
/**
   * Rotate the value by 15 bits.  Thanks to Michael for this
   *
   * @param val
   * @param rotate
   * @return int
   */
  private int rotLeft15Bit(int val, int rotate)
  {
    val = val &0x7FFF;

    for(; rotate > 0; rotate--) 
    {
      if((val & 0x4000) != 0) 
      {
        val = ((val << 1) & 0x7FFF) + 1;
      }
      else
      {
        val = (val << 1) & 0x7FFF;
      }
    }

    return val;
  }
}

public class TILESPACK1A {
