	public static long tilesPack1a(int n) {
		// stop at 0 or 1 tiles - there's only one option for that to happen
		if (n < 2) {
			return 1;
		}

		// sum the options to place a single tile and a double tile
		return tilesPack1a(n-1) + tilesPack1a(n-2);
	}
}

public class CLAMP {
/**
	 * Clamp val to be &gt;= min and &lt; max.
	 */
	private static int clamp(int val, int min, int max) {
		if (val < min) {
			return min;
		} else if (val >= max) {
			return max - 1;
		} else {
			return val;
		}
	}
}

public class X {
/**
     * Scale d by m, checking for overflow.
     * This has a short name to make above code more readable.
     */
    static long x(long d, long m, long over) {
        if (d >  over) return Long.MAX_VALUE;
        if (d < -over) return Long.MIN_VALUE;
        return d * m;
    }
}

public class ISGOODHTTPSTATUS {
/** Determines whether the specifed HTTP status code is generally "good" */
    public boolean isGoodHttpStatus(int status) {
        if ((400 <= status) && (status <= 417)) {
            return false;
        }
        if ((500 <= status) && (status <= 505)) {
            return false;
        }
        return true;
    }
}

public class CHARLENGTH {
/**
     * Finds the visual length of the character on the screen.
     * @param x
     * @return
     */
    public static int charLength(char x)
    {
        if ("i.:,;|!".indexOf(x) != -1)
        {
            return 2;
        }
        else if ("l'".indexOf(x) != -1)
        {
            return 3;
        }
        else if ("tI[]".indexOf(x) != -1)
        {
            return 4;
        }
        else if ("fk{}<>\"*()".indexOf(x) != -1)
        {
            return 5;
        }
        else if ("abcdeghjmnopqrsuvwxyzABCDEFGHJKLMNOPQRSTUVWXYZ1234567890\\/#?$%-=_+&^".indexOf(x) != -1)
        {
            return 6;
        }
        else if ("@~".indexOf(x) != -1)
        {
            return 7;
        }
        else if (x == ' ')
        {
            return 4;
        }
        else
        {
            return -1;
        }
    }
}

public class ISFILENAMECHARACTER {
/**
     * Returns whether we may want to use this character as part of a file name.
     *
     * This basically only accepts ascii letters and numbers, and rejects everything else.
     */
    private static boolean isFileNameCharacter(int codePoint) {
        if (codePoint >= 0x30 && codePoint <= 0x39) return true; // Digit
        if (codePoint >= 0x41 && codePoint <= 0x5A) return true; // Uppercase
        if (codePoint >= 0x61 && codePoint <= 0x7A) return true; // Lowercase
        return codePoint == '_'; // Underscore
    }
}

public class EQUALSIGNORECASE {
/**
     * Returns true if a and b are equal ignoring the case of the character.
     * @param a first character to check
     * @param b second character to check
     * @return {@code true} if a and b are equal, {@code false} otherwise.
     */
    public static boolean equalsIgnoreCase(char a, char b) {
        // Some language, such as Turkish, need testing both cases.
        return a == b
                || Character.toLowerCase(a) == Character.toLowerCase(b)
                || Character.toUpperCase(a) == Character.toUpperCase(b);
    }
}

