public class ISUPTODATE {
/**
     * Compare two timestamps for being up to date using
     * the specified granularity.
     *
     * @param sourceTime  timestamp of source file.
     * @param destTime    timestamp of dest file.
     * @param granularity os/filesys granularity.
     * @return true if the dest file is considered up to date.
     */
    public boolean isUpToDate(long sourceTime, long destTime, long granularity)
    {
        if (destTime == -1)
        {
            return false;
        }
        return destTime >= sourceTime + granularity;
    }
}

public class COMPUTEBINARYLOG {
/**
     * Computes floor(log_2(n)) + 1
     */
    private int computeBinaryLog(int n)
    {
        assert n >= 0;

        int result = 0;
        while (n > 0) {
            n >>= 1;
            ++result;
        }

        return result;
    }
}

public class PREPARESETTINGS {
/**
     * Its only job is to accept lots of setting flags as arguments and create a single integer
     * that represents all those settings. <b>Note</b>, that it doesn't set {@link #settingFlags settingFlags} at all,
     * it will simply return the combined setting flags. You can pass the output of this method to {@link #isSettingSet(int) isSettingSet}
     * to check for multiple settings at one call, or pass this value to constructors. 
     * @param flags The settings as arguments.
     * @return The settings ORed together. 
     */
    public static int prepareSettings(int... flags) {
	int settings = 0;
	for (int flag : flags) {
	    settings = settings | flag;
	}
	return settings;
    }
}

public class TO_SIX_BIT {
/**
     * Returns the transposed and split code of a 24-bit code
     * into a 4-byte code, each having 6 bits.
     */
    private static int to_six_bit(int num) {
        return (((num << 26) & 0xfc000000) | ((num << 12) & 0xfc0000) |
                ((num >> 2) & 0xfc00) | ((num >> 16) & 0xfc));
    }
}

public class TO_SIX_BIT {
/**
     * Returns the transposed and split code of two 24-bit code
     * into two 4-byte code, each having 6 bits.
     */
    private static long to_six_bit(long num) {
        return (((num << 26) & 0xfc000000fc000000L) | ((num << 12) & 0xfc000000fc0000L) |
                ((num >> 2) & 0xfc000000fc00L) | ((num >> 16) & 0xfc000000fcL));
    }
}

public class BINARYSIZE {
/**
     * Write to buffer (starting at index) the given number using a set of bytes
     * as required by the max possible value for the number
     * 
     * @param max
     *            The number to write
     * @return The number of bytes needed
     */
    protected static int binarySize(int max) {
        // 1 byte (2^8)
        if (max < 256) {
            return 1;
        }

        // 2 bytes (2^16)
        if (max < 65536) {
            return 2;
        }

        // 3 bytes (2^24)
        if (max < 16777216) {
            return 3;
        }

        // 4 bytes (2^32)
        return 4;
    }
}

public class GETU32 {
/**
     * Returns an unsigned 32-bit value from little-endian ordered bytes.
     *
     * @param b1 first byte value
     * @param b2 second byte value
     * @param b3 third byte value
     * @param b4 fourth byte value
     * @return an unsigned 32-bit value as a long
     */
    public static long getU32(int b1, int b2, int b3, int b4) {
        return ((b1 & 0xFF) | ((b2 & 0xFF) << 8) | ((b3 & 0xFF) << 16) | ((b4 & 0xFF) << 24)) & 0x00000000FFFFFFFFL;
    }
}

public class DIGITVALUE {
/**
     * Interpret a character as a digit (in any base up to 36) and return the numeric value. This is
     * like {@code Character.digit()} but we don't accept non-ASCII digits.
     */
    private static int digitValue(char c) {
        if (('0' <= c) && (c <= '9')) {
            return c - '0';
        } else if (('a' <= c) && (c <= 'z')) {
            return c - 'a' + 10;
        } else {
            return c - 'A' + 10;
        }
    }
}

public class COLORCOMPONENTABSOLUTE {
/**
     * Defines a simple function for a color.
     * 
     * @param value
     * @param bLeft under this value, the color is 0
     * @param bRight up to this value, the color is 0
     * @param tLeft from this value until @link tRight, the color is 1
     * @param tRight from @link tLeft until this value, the color is 1
     * 
     * Between bLeft and tLeft, as well as tRight and bRight, the output value is a linear
     * interpolation between 0 and 1.
     * 
     * <code>
     *                      tLeft       tRight
     *                        /-----------\
     *                       /             \ 
     *                      /               \
     *              -------|-----------------|--------
     *                    bLeft            bRight  
     * </code>
     * 
     * @return color influence.
     */
    private float colorComponentAbsolute( float value, float bLeft, float bRight, float tLeft, float tRight ){
        float output = 0;
        // a gauche ou a droite du creneau
        if( (value < bLeft) || (value >= bRight) ){
            output = 0;
        }
        // sur le plateau haut
        else if( (value >= tLeft) && (value < tRight) ){
            output = 1;
        }
        // sur la pente gauche du creneau
        else if( (value >= bLeft) && (value < tLeft) ){
            output = (value-bLeft)/(tLeft-bLeft);
        }
        // sur la pente droite du creneau
        else if( (value >= tRight) && (value < bRight) ){
            output = (value-bRight)/(tRight-bRight);
        }
        return output;
    }
}

