     * Returns the number of ticks a timer torch (and perhaps delay torch) should wait
     * before reverting.  Not using system clock, because lag will throw off calculations.
     * @param seconds number of seconds in 0.0
     * @return the number of ticks in the given number of seconds.
     */
    public static long secondsToTicks(double seconds){
        double t = seconds * 20; //20 ticks per second, in an ideal world.
        return Math.round(t);
    }
}

public class BINROOT {
/**
     * Bin root - a binary search for a square root.
     * I wrote this purely to check my recollection
     * of how this kind of search can be used to invert
     * functions.
     */

    private static double binRoot(double x) {
        double eps = 0.0001; // accuracy
        // do a binary search for it
        // find the square root of x using a binary search
        double lower = 0.0;
        double upper = x;
        double mid = 0.0;


        for (int i = 0; i < 100; i++) {
            mid = (lower + upper) / 2;
            // each time, if mid is too big
            // fix lower to mid
            // else fix upper to mid

            double cur = mid * mid;
            if (Math.abs(x - cur) < eps) {
                // System.out.println("Converged to " + cur + " in " + i + " iterations");
                return mid;
            }

            if (cur < x) // mid too small
                lower = mid;
            else // mid too big
                upper = mid;
        }
        return mid;
    }
}

public class VOCALTRACTCOMPENSATION {
/**
     * Compensation of the vocal tract influence
     * @param freq
     * @param formant
     * @param bandWidth
     * @return
     */   
    public double vocalTractCompensation(double freq, double formant, double bandWidth){
      double num, denom, aux, val;     
      aux = Math.pow((bandWidth/2), 2.0);
      num = Math.pow(formant, 2.0) + aux;
      denom = Math.sqrt( ( Math.pow((freq-formant), 2.0) + aux )*( Math.pow((freq+formant), 2.0) + aux) );
      val = (num/denom);
      if(val > 0.0)
        return (20 * Math.log10(val));
      else{
        System.out.println("vocalTractCompensation: warning value < 0.0");
        return 0.0;
      }      
    }
}

public class HYPOT {
/** sqrt(a^2 + b^2) without under/overflow. **/



   public static double hypot(double a, double b) {

      double r;

      if (Math.abs(a) > Math.abs(b)) {

         r = b/a;

         r = Math.abs(a)*Math.sqrt(1+r*r);

      } else if (b != 0) {

         r = a/b;

         r = Math.abs(b)*Math.sqrt(1+r*r);

      } else {

         r = 0.0;

      }

      return r;

   }
}

public class BANDWIDTH2KERNELLENGTH {
/**
     * Convert from normalisedTransitionBandwidth to filter kernel length,
     * using the approximate formula l = 4/bw. 
     * @param normalisedTransitionBandwidth
     * @return the corresponding filter kernel length (guaranteed to be an odd number).
     */
    protected static int bandwidth2kernelLength(double normalisedTransitionBandwidth)
    {
        int l = (int) (4/normalisedTransitionBandwidth);
        // kernel length must be odd:
        if (l%2==0) l++;
        return l;
    }
}

public class BYTESWAP {
/**
     * Byte swapping for int values.
     * 
     * @param val
     * @return
     */
    private static int byteswap( int val ) {
        return( ( (val & 0xff000000) >>> 24)
                 + ( (val & 0x00ff0000) >>> 8)
                 + ( (val & 0x0000ff00) << 8)
                 + ( (val & 0x000000ff) << 24) );
     }
}

public class HZ2BARK {
/**
     * Since there is no asinh in Math, here it is used its definition:
     * asinh(x) = ln( x + sqrt(x^2+1) )
     * This function is used in fft2barkmx()
     */
    public static double hz2bark(double freqInHz)
    {
        // if should be: return 6 * asinh(f/600);
        double f = freqInHz/600;
        return 6 * Math.log( f + Math.sqrt((f*f)+1) );
    }
}

