public class RGBA {
/**
     * Get the color code for the given red, green, blue, and alpha values as
     * floating point numbers in the range 0-1.0.
     * @param r the red color component (in the range 0-1.0)
     * @param g the green color component (in the range 0-1.0)
     * @param b the blue color component (in the range 0-1.0)
     * @param a the alpha (transparency) component (in the range 0-1.0)
     * @return the integer color code
     */
    public static int rgba(float r, float g, float b, float a) {
        return ((((int) (a * 255 + 0.5)) & 0xFF) << 24)
                | ((((int) (r * 255 + 0.5)) & 0xFF) << 16)
                | ((((int) (g * 255 + 0.5)) & 0xFF) << 8)
                | (((int) (b * 255 + 0.5)) & 0xFF);
    }
}

public class DESATURATE {
/**
     * Get a desaturated shade of an input color.
     * @param c a color code
     * @return a desaturated color code
     */
    public static int desaturate(int c) {
        int a = c & 0xff000000;
        float r = ((c & 0xff0000) >> 16);
        float g = ((c & 0x00ff00) >> 8);
        float b = (c & 0x0000ff);

        r *= 0.2125f; // red band weight
        g *= 0.7154f; // green band weight
        b *= 0.0721f; // blue band weight

        int gray = Math.min(((int) (r + g + b)), 0xff) & 0xff;
        return a | (gray << 16) | (gray << 8) | gray;
    }
}

public class LINEARINTERP {
/**
     * Interpolates a value between a given minimum and maximum value using
     * a linear scale.
     * @param val the interpolation value, a fraction between 0 and 1.0.
     * @param min the minimum value of the interpolation range
     * @param max the maximum value of the interpolation range
     * @return the resulting interpolated value
     */
    public static double linearInterp(double val, double min, double max) {
        double denominator = (max-min);
        if ( denominator == 0 )
            return 0;
        return (val-min)/denominator;
    }
}

public class ADJUSTCOLORCOMPONENT {
/**
     * Adjust an rgb color component.
     *
     * @param base the color, an RGB value 0-255
     * @param adjBright the amount to subtract if base > 128
     * @param adjDark the amount to add if base <=128
     */
    private static int adjustColorComponent(int base, int adjBright, int adjDark) {
        if (base > 128) {
            base -= adjBright;
        } else {
            base += adjDark;
        }

        if (base < 0) {
            base = 0;
        }

        if (base > 255) {
            base = 255;
        }

        return base;
    }
}

public class EVAL {
/**
         * use Bernstein basis to evaluate 1D cubic Bezier curve (quicker and more
         * numerically stable than power basis) -- 1D control coordinates are
         * (0, p1, p2, 1), where p1 and p2 are in range [0,1], and there is no
         * ordering constraint on p1 and p2, i.e., p1 <= p2 does not have to be true
         * @param t is the paramaterized value in range [0,1]
         * @param p1 is 1st control point coordinate in range [0,1]
         * @param p2 is 2nd control point coordinate in range [0,1]
         * @return the value of the Bezier curve at parameter t
         */
        private float eval(float t, float p1, float p2) {
            // Use optimzied version of the normal Bernstein basis form of Bezier:
            // (3*(1-t)*(1-t)*t*p1)+(3*(1-t)*t*t*p2)+(t*t*t), since p0=0, p3=1
            // The above unoptimized version is best using -server, but since we are
            // probably doing client-side animation, this is faster.
            float compT = 1 - t;
            return t * (3 * compT * (compT * p1 + t * p2) + (t * t));
        }
}

public class EVALDERIVATIVE {
/**
         * evaluate Bernstein basis derivative of 1D cubic Bezier curve, where 1D
         * control points are (0, p1, p2, 1), where p1 and p2 are in range [0,1], and
         * there is no ordering constraint on p1 and p2, i.e., p1 <= p2 does not have
         * to be true
         * @param t is the paramaterized value in range [0,1]
         * @param p1 is 1st control point coordinate in range [0,1]
         * @param p2 is 2nd control point coordinate in range [0,1]
         * @return the value of the Bezier curve at parameter t
         */
        private float evalDerivative(float t, float p1, float p2) {
            // use optimzed version of Berstein basis Bezier derivative:
            // (3*(1-t)*(1-t)*p1)+(6*(1-t)*t*(p2-p1))+(3*t*t*(1-p2)), since p0=0, p3=1
            // The above unoptimized version is best using -server, but since we are
            // probably doing client-side animation, this is faster.
            float compT = 1 - t;
            return 3 * (compT * (compT * p1 + 2 * t * (p2 - p1)) + t * t * (1 - p2));
        }
}

public class EXTRACT {
/**
	 * Mask out and shift a bit substring.
	 * 
	 * @param bits
	 *            the bit string.
	 * @param lowest
	 *            the first bit of the substring within the string.
	 * @param size
	 *            the number of bits in the substring.
	 * @return the substring.
	 */
	public static int extract(int bits, int lowest, int size) {
		if (size == 32)
			return (bits >> lowest);
		else
			return ((bits >> lowest) & ((1 << size) - 1));
	}
}

public class EXTRACT {
/**
	 * Mask out and shift a bit substring.
	 * 
	 * @param bits
	 *            the bit string.
	 * @param lowest
	 *            the first bit of the substring within the string.
	 * @param size
	 *            the number of bits in the substring.
	 * @return the substring.
	 */
	public static long extract(long bits, int lowest, int size) {
		if (size == 64)
			return (bits >> lowest);
		else
			return ((bits >> lowest) & ((1L << size) - 1));
	}
}

public class POINTDELTA {
/**
     * Calculate how far the points would be apart, given the specified amount and whether the geometry is closed.
     *
     * @param amount the amount of points
     * @param closed whether the geometry is closed
     * @return the delta value between each point
     */
    protected double pointDelta(int amount, boolean closed) {
        double delta = 1;
        if (closed) {
            if (amount > 0) {
                delta = 1.0 / amount;
            }
        } else {
            // The delta value is divided by amount - 1, because we also want the last point (t=1.0)
            // If I wouldn't use amount - 1, I fall one point short of the end.
            // E.g. if amount = 4, I want point at t 0.0, 0.33, 0.66 and 1.0,
            // if amount = 2, I want point at t 0.0 and t 1.0
            if (amount > 2) {
                delta = 1.0 / (amount - 1.0);
            }
        }
        return delta;
    }
}

public class LINELENGTH {
/**
     * Returns the length of the line.
     *
     * @param x0 X start coordinate
     * @param y0 Y start coordinate
     * @param x1 X end coordinate
     * @param y1 Y end coordinate
     * @return the length of the line
     */
    public static double lineLength(double x0, double y0, double x1, double y1) {
        x0 = Math.abs(x0 - x1);
        x0 *= x0;
        y0 = Math.abs(y0 - y1);
        y0 *= y0;
        return Math.sqrt(x0 + y0);
    }
}

public class EXTRACT {
/**
	 * Get part of one integer as a new integer
	 * 
	 * @param bs
	 *            original integer
	 * @param low
	 *            the low bit position (inclusive), 0 base
	 * @param high
	 *            the hight bit position (exclusive), 0 base
	 * @return new integer
	 */
	public static int extract(int bs, int low, int high) {
		bs = bs >> low;
		int mask = 0;
		for (int i = 0; i < (high - low); i++) {
			mask += 1 << i;
		}
		return bs & mask;
	}
}

public class EXTRACT {
/**
	 * Get part of one integer as a new integer
	 * 
	 * @param bs
	 *            original integer
	 * @param low
	 *            the low bit position (inclusive), 0 base
	 * @param hight
	 *            the hight bit position (exclusive), 0 base
	 * @return
	 */
	public static int extract(int bs, int low, int high) {
		bs = bs >> low;
		int mask = 0;
		for (int i = 0; i < (high - low); i++) {
			mask += 1 << i;
		}
		return bs &= mask;
	}
}

public class GETANGLEFORVALUE {
/**
   * Returns the angle for a specific chart value.
   * 
   * @param value the chart value
   * @param minAngle the minimum chart angle value
   * @param maxAngle the maximum chart angle value
   * @param min the minimum chart value
   * @param max the maximum chart value
   * @return the angle
   */
  private double getAngleForValue(double value, double minAngle, double maxAngle, double min,
      double max) {
    double angleDiff = maxAngle - minAngle;
    double diff = max - min;
    return Math.toRadians(minAngle + (value - min) * angleDiff / diff);
  }
}

public class ROUNDUP {
/**
   * Given a number, round up to the nearest power of ten times 1, 2, or 5. The
   * argument must be strictly positive.
   */
  private static double roundUp(final double val) {
    int exponent = (int) Math.floor(Math.log10(val));
    double rval = val * Math.pow(10, -exponent);
    if (rval > 5.0) {
      rval = 10.0;
    } else if (rval > 2.0) {
      rval = 5.0;
    } else if (rval > 1.0) {
      rval = 2.0;
    }
    rval *= Math.pow(10, exponent);
    return rval;
  }
}

public class FITTOCOLOR {
/**
	 * Makes sure that an adjustment by this amount for this part of the color
	 * wont overflow (which will cause the overall color to change)
	 * 
	 * @param color
	 * @param change
	 * @return
	 */
	private static int fitToColor(int color, int change) {
		if(color + change < 0 || color + change > 255)
			return 255 - color;
		return change;
	}
}

public class GETOPPOSITEDIRECTION {
/**
	 * Given the direction of the bond from ring1 to ring2, returns the opposite direction: from ring2 to ring1
	 * @param prevDir
	 * @return
	 */
	static int getOppositeDirection(int prevDir) {
		int dir;
		if (prevDir == 0) {
			dir = 4;
		}
		else if (Math.abs(prevDir) == 4){
			dir =0;
		}
		else if (Math.abs(prevDir) == 2){
			dir = 2 * -1 * Integer.signum(prevDir);
		}
		else if (Math.abs(prevDir) == 1){
			dir = 3 * -1 * Integer.signum(prevDir);
		}
		else {//prevDir will be +-3
			dir = 1 * -1 * Integer.signum(prevDir);
		}
		return dir;
	}
}

public class COUNTDX {
/**
	 * Counts delta x distance between previous and next rings
	 * @param val
	 * @return
	 */
	private static float countDX (int val) {
		float dX = 0;
		if (Math.abs(val) == 1) {
			dX += 0.5f;
		}
		else if (Math.abs(val) == 3) {
			dX -= 0.5f;
		}
		else if (Math.abs(val) == 0) {
			dX += 1f;
		}
		else if (Math.abs(val) == 4) {
			dX -= 1f;
		}
		return dX;
	}
}

public class COUNTDY {
/**
	 * Counts delta y distance (height) between previous and next rings
	 * @param val
	 * @return
	 */

	private static int countDY (int val) {
		int dY = 0;
		if (Math.abs(val) != 4) {
			if (val > 0) {
				dY = 1;
			}
			if (val < 0) {
				dY = -1;
			}
		}
		return dY;
	}
}

