public class ISOPERATORCHAR {
/**
     * @return true if the given character is a valid character for an
     *         operator in the backend's parser
     */
    public static boolean isOperatorChar(char c) {
        /*
         * Extracted from operators defined by {self} and {op_chars}
         * in pgsql/src/backend/parser/scan.l.
         */
        return ",()[].;:+-*/%^<>=~!@#&|`?".indexOf(c) != -1;
    }
}

public class ISIDENTIFIERSTARTCHAR {
/**
     * Checks if a character is valid as the start of an identifier.
     * 
     * @param c the character to check
     * @return true if valid as first character of an identifier; false if not
     */
    public static boolean isIdentifierStartChar(char c) {
        /*
         * Extracted from {ident_start} and {ident_cont} in
         * pgsql/src/backend/parser/scan.l:
         * ident_start    [A-Za-z\200-\377_]
         * ident_cont     [A-Za-z\200-\377_0-9\$]
         */
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
                || c == '_' || c > 127 ;
    }
}

public class ISIDENTIFIERCONTCHAR {
/**
     * Checks if a character is valid as the second or later character of an
     * identifier.
     * 
     * @param c the character to check
     * @return true if valid as second or later character of an identifier; false if not
     */
    public static boolean isIdentifierContChar(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
                || c == '_' || c > 127
                || (c >= '0' && c <= '9')
                || c == '$';
    }
}

public class ISDOLLARQUOTESTARTCHAR {
/**
     * Checks if a character is valid as the start of a dollar quoting tag.
     * 
     * @param c the character to check
     * @return true if valid as first character of a dollar quoting tag; false if not
     */
    public static boolean isDollarQuoteStartChar(char c) {
        /*
         * The allowed dollar quote start and continuation characters
         * must stay in sync with what the backend defines in
         * pgsql/src/backend/parser/scan.l
         */
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
                || c == '_' || c > 127;
    }
}

public class ISDOLLARQUOTECONTCHAR {
/**
     * Checks if a character is valid as the second or later character of a
     * dollar quoting tag.
     * 
     * @param c the character to check
     * @return true if valid as second or later character of a dollar quoting tag;
     *         false if not
     */
    public static boolean isDollarQuoteContChar(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
                || c == '_' || c > 127
                || (c >= '0' && c <= '9');
    }
}

public class TOJAVASECS {
/**
     * Converts the given postgresql seconds to java seconds.
     * Reverse engineered by inserting varying dates to postgresql
     * and tuning the formula until the java dates matched.
     * See {@link #toPgSecs} for the reverse operation.
     * 
     * @param secs Postgresql seconds.
     * @return Java seconds.
     */
    private static long toJavaSecs(long secs) {
        // postgres epoc to java epoc
        secs += 946684800L;

        // Julian/Gregorian calendar cutoff point
        if (secs < -12219292800L) { // October 4, 1582 -> October 15, 1582
            secs += 86400 * 10;
            if (secs < -14825808000L) { // 1500-02-28 -> 1500-03-01
                int extraLeaps = (int) ((secs + 14825808000L) / 3155760000L);
                extraLeaps--;
                extraLeaps -= extraLeaps / 4;
                secs += extraLeaps * 86400L;
            }
        }
        return secs;
    }
}

public class TOPGSECS {
/**
     * Converts the given java seconds to postgresql seconds.
     * See {@link #toJavaSecs} for the reverse operation.
     * The conversion is valid for any year 100 BC onwards.
     * 
     * @param secs Postgresql seconds.
     * @return Java seconds.
     */
     private static long toPgSecs(long secs) {
        // java epoc to postgres epoc
        secs -= 946684800L;

        // Julian/Greagorian calendar cutoff point
        if (secs < -13165977600L) { // October 15, 1582 -> October 4, 1582
            secs -= 86400 * 10;
            if (secs < -15773356800L) { // 1500-03-01 -> 1500-02-28
                int years = (int) ((secs + 15773356800L) / -3155823050L);
                years++;
                years -= years/4;
                secs += years * 86400;
            }
        }

        return secs;
    }
}

public class COMPUTESLOWINSLOWOUT {
/**
     * Computes percent or linear interpolation to apply when taking
     * acceleration into account.
     * 
     * @param zeroToOne Percentage of activity completed
     * @return strength of acceleration
     */
    public float computeSlowInSlowOut(final float zeroToOne) {
        if (zeroToOne < 0.5f) {
            return 2.0f * zeroToOne * zeroToOne;
        }
        else {
            final float complement = 1.0f - zeroToOne;
            return 1.0f - 2.0f * complement * complement;
        }
    }
}

public class CONTAINS {
/**
     * Returns whether the given coordinates are on the line defined by (x1,y1)
     * and (x2,y2) within the given distance.
     * 
     * @param x x component of point being tested
     * @param y y component of point being tested
     * @param x1 x component of start point of line segment
     * @param y1 y component of start point of line segment
     * @param x2 x component of end point of line segment
     * @param y2 y component of end point of line segment
     * @param min whether the point should be constrained to "after" the start
     *            of the segment
     * @param max whether the point should be constrained to "before" the end of
     *            the segment
     * @param distance distance from line acceptable as "touching"
     * @return whether the point (x,y) is near enough to the given line
     */
    public static boolean contains(final double x, final double y, final double x1, final double y1, final double x2,
            final double y2, final boolean min, final boolean max, final double distance) {
        double dx = x2 - x1;
        double dy = y2 - y1;

        // If line is a point then bail out
        if (dx == 0 && dy == 0) {
            return false;
        }

        final double dx2 = dx * dx;
        final double dy2 = dy * dy;

        // distance along segment as a ratio or the (x1,y1)->(x2,y2) vector
        final double p;
        if (dx != 0) {
            p = ((x - x1) / dx + dy * (y - y1) / dx2) / (1 + dy2 / dx2);
        }
        else {
            p = ((y - y1) / dy + dx * (x - x1) / dy2) / (1 + dx2 / dy2);
        }

        // Point is not "beside" the segment and it's been disallowed, bail.
        if (min && p < 0 || max && p > 1.0) {
            return false;
        }

        dx = p * dx + x1 - x;
        dy = p * dy + y1 - y;

        final double len = dx * dx + dy * dy;
        return len < distance;
    }
}

public class INTERSECTS {
/**
     * Returns true if the two segments defined by (x1,y1)->(x2,y2) and
     * (x3,y3)->(x4,y4) intersect. Optional fields allow for consideration of
     * extending the segments to infinity at either end.
     * 
     * @param x1 segment 1's start x component
     * @param y1 segment 1's start y component
     * @param x2 segment 1's end x component
     * @param y2 segment 1's end y component
     * @param x3 segment 2's start x component
     * @param y3 segment 2's start y component
     * @param x4 segment 2's end x component
     * @param y4 segment 2's end y component
     * @param min1 whether the second segment is acceptable if it passes
     *            "before the start of the first segment"
     * @param max1 whether the second segment is acceptable if it passes
     *            "after the end of the first segment"
     * @param min2 whether the first segment is acceptable if it passes
     *            "before the start of the second segment"
     * @param max2 whether the first segment is acceptable if it passes
     *            "after the start of the second segment"
     * @return true if line segments intersect
     */
    public static boolean intersects(final double x1, final double y1, final double x2, final double y2,
            final double x3, final double y3, final double x4, final double y4, final boolean min1, final boolean max1,
            final boolean min2, final boolean max2) {
        final double dx1 = x2 - x1, dy1 = y2 - y1, dx2 = x4 - x3, dy2 = y4 - y3;
        double d, p2, p1;

        if (dy1 != 0.0) {
            d = dx1 / dy1;
            p2 = (x3 - x1 + d * (y1 - y3)) / (d * dy2 - dx2);
            p1 = (dy2 * p2 + y3 - y1) / dy1;
        }
        else if (dy2 != 0.0) {
            d = dx2 / dy2;
            p1 = (x1 - x3 + d * (y3 - y1)) / (d * dy1 - dx1);
            p2 = (dy1 * p1 + y1 - y3) / dy2;
        }
        else if (dx1 != 0.0) {
            d = dy1 / dx1;
            p2 = (y3 - y1 + d * (x1 - x3)) / (d * dx2 - dy2);
            p1 = (dx2 * p2 + x3 - x1) / dx1;
        }
        else if (dx2 != 0.0) {
            d = dy2 / dx2;
            p1 = (y1 - y3 + d * (x3 - x1)) / (d * dx1 - dy1);
            p2 = (dx1 * p1 + x1 - x3) / dx2;
        }
        else {
            return false;
        }
        return (!min1 || p1 >= 0.0) && (!max1 || p1 <= 1.0) && (!min2 || p2 >= 0.0) && (!max2 || p2 <= 1.0);
    }
}

