public class CEILDIV {
/**
	 * Helper function.
	 * 
	 * @param a
	 *            dividend
	 * @param b
	 *            divisor
	 * @return a/b if a%b==0 else a/b+1, while <code>/</code> is meant as integer division
	 */
	public static int ceilDiv(int a, int b) {
		if (a % b == 0) {
			return a / b;
		} else {
			return a / b + 1;
		}
	}
}

