public class GREGORIANTOJD {
/**
    * Convert from a gregorian date to a julian day.
    */
   public double gregoriantojd(int month, int day, int year) {
      if (month <= 2) {
         year -= 1;
         month += 12;
      }

      long a = year / 100;
      long b = a / 4;
      long c = 2 - a + b;
      long e = (long) (365.25 * (year + 4716));
      long f = (long) (30.6001 * (month + 1));

      return (c + day + e + f - 1524.5);
   }
}

public class ENCODE {
/**
    * Converts an integer to a printable character
    */
   private static char encode(long code) {
      code = code & 0x3f;

      if (code < 26) {
         return (char) ('a' + code);
      } else if (code < 52) {
         return (char) ('A' + code - 26);
      } else if (code < 62) {
         return (char) ('0' + code - 52);
      } else if (code == 62) {
         return '_';
      } else {
         return '-';
      }
   }
}

public class TOUPPERCASE {
/**
    * Returns the uppercase equivalent of the caharacter
    */
   protected static char toUpperCase(char ch) {
      if (ch >= 'a' && ch <= 'z') {
         return (char) ('A' + (ch - 'a'));
      } else {
         return ch;
      }
   }
}

public class TOUUCHAR {
/**
    * Converts an integer digit to a uuencoded char.
    */
   protected static char toUUChar(int d) {
      if (d == 0) {
         return (char) 0x60;
      } else {
         return (char) (0x20 + (d & 0x3f));
      }
   }
}

public class YEARTODAYOFEPOCH {
/**
   * Based on the year, return the number of days since the epoch.
   */
  private long yearToDayOfEpoch(long year)
  {
    if (year > 0) {
      year -= 1601;
      return (365 * year + year / 4 - year / 100 + year / 400 -
              ((1970 - 1601) * 365 + (1970 - 1601) / 4 - 3));
    } else {
      year = 2000 - year;

      return ((2000 - 1970) * 365 + (2000 - 1970) / 4 -
              (365 * year + year / 4 - year / 100 + year / 400));
    }
  }
}

public class TOYEAR {
/**
	 * translate 2 digit numbers to a year; for example 10 to 2010 or 50 to 1950
	 * @param year
	 * @return year matching number
	 */
	public int toYear(int year) {
		if(year<100) {
    	    if(year<30)year=year+=2000;
            else year=year+=1900;
        }
		return year;
	}
}

public class UPDATEMODE {
/** 
     * update octal mode with a other 
     * @param existingOctal 
     * @param updateOctal 
     * @return 
     */ 
    public static int updateMode(int existingOctal, int updateOctal) { 
            int tmp=existingOctal&updateOctal; 
            return (existingOctal-tmp)+updateOctal; 
    }
}

public class MOD {
/**
	 * Return a mod b. This differs from the % operator with respect to negative numbers.
	 * @param a the dividend
	 * @param b the divisor
	 * @return a mod b
	 */
	private static int mod(int a, int b) {
		int n = a/b;

		a -= n*b;
		if (a < 0)
			return a + b;
		return a;
	}
}

public class GETCOLOR {
/**
	 * Convert a value in the range 0..1 to an RGB color.
	 * @param v a value in the range 0..1
	 * @return an RGB color
	 */
	public int getColor(float v) {
		int n = (int)(v*255);
		if (n < 0)
			n = 0;
		else if (n > 255)
			n = 255;
		return 0xff000000 | (n << 16) | (n << 8) | n;
	}
}

public class GAIN {
/**
	 * A variant of the gamma function.
	 * @param a the number to apply gain to
	 * @param b the gain parameter. 0.5 means no change, smaller values reduce gain, larger values increase gain.
	 * @return the output value
	 */
	public static float gain(float a, float b) {
/*
		float p = (float)Math.log(1.0 - b) / (float)Math.log(0.5);

		if (a < .001)
			return 0.0f;
		else if (a > .999)
			return 1.0f;
		if (a < 0.5)
			return (float)Math.pow(2 * a, p) / 2;
		else
			return 1.0f - (float)Math.pow(2 * (1. - a), p) / 2;
*/
		float c = (1.0f/b-2.0f) * (1.0f-2.0f*a);
		if (a < 0.5)
			return a/(c+1.0f);
		return (c-a)/(c-1.0f);
	}
}

public class SMOOTHPULSE {
/**
	 * A smoothed pulse function. A cubic function is used to smooth the step between two thresholds.
	 * @param a1 the lower threshold position for the start of the pulse
	 * @param a2 the upper threshold position for the start of the pulse
	 * @param b1 the lower threshold position for the end of the pulse
	 * @param b2 the upper threshold position for the end of the pulse
	 * @param x the input parameter
	 * @return the output value
	 */
	public static float smoothPulse(float a1, float a2, float b1, float b2, float x) {
		if (x < a1 || x >= b2)
			return 0;
		if (x >= a2) {
			if (x < b1)
				return 1.0f;
			x = (x - b1) / (b2 - b1);
			return 1.0f - (x*x * (3.0f - 2.0f*x));
		}
		x = (x - a1) / (a2 - a1);
		return x*x * (3.0f - 2.0f*x);
	}
}

public class SMOOTHSTEP {
/**
	 * A smoothed step function. A cubic function is used to smooth the step between two thresholds.
	 * @param a the lower threshold position
	 * @param b the upper threshold position
	 * @param x the input parameter
	 * @return the output value
	 */
	public static float smoothStep(float a, float b, float x) {
		if (x < a)
			return 0;
		if (x >= b)
			return 1;
		x = (x - a) / (b - a);
		return x*x * (3 - 2*x);
	}
}

public class CIRCLEUP {
/**
	 * A "circle up" function. Returns y on a unit circle given 1-x. Useful for forming bevels.
	 * @param x the input parameter in the range 0..1
	 * @return the output value
	 */
	public static float circleUp(float x) {
		x = 1-x;
		return (float)Math.sqrt(1-x*x);
	}
}

