public class ZETASTATIC {
/**
	 * Compute the zeta constant needed for the distribution. Do this incrementally for a distribution that
	 * has n items now but used to have st items. Use the zipfian constant theta. Remember the new value of 
	 * n so that if we change the itemcount, we'll know to recompute zeta. 
	 * @param st The number of items used to compute the last initialsum
	 * @param n The number of items to compute zeta over.
	 * @param theta The zipfian constant.
     * @param initialsum The value of zeta we are computing incrementally from.
	 */
	static double zetastatic(long st, long n, double theta, double initialsum)
	{
		double sum=initialsum;
		for (long i=st; i<n; i++)
		{

			sum+=1/(Math.pow(i+1,theta));
		}

		//System.out.println("countforzeta="+countforzeta);

		return sum;
	}
}

public class UNRANDOMIZE255STATE {
/**
   * See ISO 16022:2006, Annex B, B.2
   */
  private static int unrandomize255State(int randomizedBase256Codeword,
                                          int base256CodewordPosition) {
    int pseudoRandomNumber = ((149 * base256CodewordPosition) % 255) + 1;
    int tempVariable = randomizedBase256Codeword - pseudoRandomNumber;
    return tempVariable >= 0 ? tempVariable : tempVariable + 256;
  }
}

public class CALCULATENUMBEROFROWS {
/**
   * Calculates the necessary number of rows as described in annex Q of ISO/IEC 15438:2001(E).
   *
   * @param m the number of source codewords prior to the additional of the Symbol Length
   *          Descriptor and any pad codewords
   * @param k the number of error correction codewords
   * @param c the number of columns in the symbol in the data region (excluding start, stop and
   *          row indicator codewords)
   * @return the number of rows in the symbol (r)
   */
  private static int calculateNumberOfRows(int m, int k, int c) {
    int r = ((m + 1 + k) / c) + 1;
    if (c * r >= (m + 1 + k + c)) {
      r--;
    }
    return r;
  }
}

public class GETNUMBEROFPADCODEWORDS {
/**
   * Calculates the number of pad codewords as described in 4.9.2 of ISO/IEC 15438:2001(E).
   *
   * @param m the number of source codewords prior to the additional of the Symbol Length
   *          Descriptor and any pad codewords
   * @param k the number of error correction codewords
   * @param c the number of columns in the symbol in the data region (excluding start, stop and
   *          row indicator codewords)
   * @param r the number of rows in the symbol
   * @return the number of pad codewords
   */
  private static int getNumberOfPadCodewords(int m, int k, int c, int r) {
    int n = c * r - k;
    return n > m + 1 ? n - m - 1 : 0;
  }
}

public class GETERRORCORRECTIONCODEWORDCOUNT {
/**
   * Determines the number of error correction codewords for a specified error correction
   * level.
   *
   * @param errorCorrectionLevel the error correction level (0-8)
   * @return the number of codewords generated for error correction
   */
  static int getErrorCorrectionCodewordCount(int errorCorrectionLevel) {
    if (errorCorrectionLevel < 0 || errorCorrectionLevel > 8) {
      throw new IllegalArgumentException("Error correction level must be between 0 and 8!");
    }
    return 1 << (errorCorrectionLevel + 1);
  }
}

public class GETDATAMASKBIT {
/**
   * Return the mask bit for "getMaskPattern" at "x" and "y". See 8.8 of JISX0510:2004 for mask
   * pattern conditions.
   */
  static boolean getDataMaskBit(int maskPattern, int x, int y) {
    int intermediate;
    int temp;
    switch (maskPattern) {
      case 0:
        intermediate = (y + x) & 0x1;
        break;
      case 1:
        intermediate = y & 0x1;
        break;
      case 2:
        intermediate = x % 3;
        break;
      case 3:
        intermediate = (y + x) % 3;
        break;
      case 4:
        intermediate = ((y >>> 1) + (x / 3)) & 0x1;
        break;
      case 5:
        temp = y * x;
        intermediate = (temp & 0x1) + (temp % 3);
        break;
      case 6:
        temp = y * x;
        intermediate = ((temp & 0x1) + (temp % 3)) & 0x1;
        break;
      case 7:
        temp = y * x;
        intermediate = ((temp % 3) + ((y + x) & 0x1)) & 0x1;
        break;
      default:
        throw new IllegalArgumentException("Invalid mask pattern: " + maskPattern);
    }
    return intermediate == 0;
  }
}

public class COMPARE {
/**
     * Compare two times.
     * @param t1 the first time to compare.
     * @param t2 the second time to compare.
     * @param g the timestamp granularity.
     * @return a negative integer, a positive integer, or zero as t1 is
     *         before, after, or equal to t2 accounting for the specified granularity.
     */
    public static int compare(long t1, long t2, long g) {
        long diff = t1 - t2;
        long abs = Math.abs(diff);
        return abs > Math.abs(g) ? (int) (diff / abs) : 0;
    }
}

public class ISLEGALCHARACTER {
/**
     * Is the given character allowed inside an XML document?
     *
     * <p>See XML 1.0 2.2 <a
     * href="http://www.w3.org/TR/1998/REC-xml-19980210#charsets">
     * http://www.w3.org/TR/1998/REC-xml-19980210#charsets</a>.</p>
     * @param c the character to test.
     * @return true if the character is allowed.
     * @since 1.10, Ant 1.5
     */
    public boolean isLegalCharacter(final char c) {
        // CheckStyle:MagicNumber OFF
        if (c == 0x9 || c == 0xA || c == 0xD) {
            return true;
        } else if (c < 0x20) {
            return false;
        } else if (c <= 0xD7FF) {
            return true;
        } else if (c < 0xE000) {
            return false;
        } else if (c <= 0xFFFD) {
            return true;
        }
        // CheckStyle:MagicNumber ON
        return false;
    }
}

public class ADJUSTTOLONG {
/**
     * Assumes a negative integer really is a positive integer that
     * has wrapped around and re-creates the original value.
     * @param i the value to treat as unsigned int.
     * @return the unsigned int as a long.
     * @since 1.34
     */
    protected static long adjustToLong(int i) {
        if (i < 0) {
            return 2 * ((long) Integer.MAX_VALUE) + 2 + i;
        } else {
            return i;
        }
    }
}

public class GETCOMPONENTINDEX {
/** Given one of the constants for a component, determine the corresponding array index. */

  private int getComponentIndex(int component)
  {
    int index = 0;
    while (((component>>index)&1) == 0)
      index++;
    return index;
  }
}

public class FLOATTOINT {
/** Convert a floating point value to an appropriate int value.  This is used by rebuildImage(). */

  private int floatToInt(float f)
  {
    int i = (int) (f*255.0f);
    if (i < 0)
      i = 0;
    if (i > 255)
      i = 255;
    return i;
  }
}

public class FLOOR {
/** A faster replacement for Math.floor(). */

  private static int floor(double d)
  {
    if (d < 0.0)
    {
      int f = (int) d;
      if (f != d)
        f -= 1;
      return f;
    }
    return (int) d;
  }
}

public class FLOOR {
/**
   * This method produces identical results to Math.floor() for all normal input values
   * (one which fall inside the allowed range of the int type).
   */

  public static int floor(double d)
  {
    if (d < 0.0)
    {
      int f = (int) d;
      if (f != d)
        f -= 1;
      return f;
    }
    return (int) d;
  }
}

public class CEIL {
/**
   * This method produces identical results to Math.ceil() for all normal input values
   * (one which fall inside the allowed range of the int type).
   */

  public static int ceil(double d)
  {
    if (d > 0.0)
    {
      int f = (int) d;
      if (f != d)
        f += 1;
      return f;
    }
    return ((int) d);
  }
}

public class POW {
/**
   * This method produces results which are nearly identical to Math.pow(), although the
   * last few digits may be different due to numerical error.  Unlike Math.pow(), this
   * method requires the exponent to be an integer.
   */

  public static double pow(double base, int exponent)
  {
    if (exponent < 0)
    {
      exponent = -exponent;
      base = 1.0/base;
    }
    double result = 1.0;
    while (exponent != 0)
    {
      if ((exponent&1) == 1)
        result *= base;
      base *= base;
      exponent = exponent>>1;
    }
    return result;
  }
}

public class ATAN {
/**
   * This method calculates a fast approximation to the arctan function.  It differs from
   * the true value by no more than 0.005 for any input value.
   * <p>
   * I found this formula on an internet discussion board post by Ranko Bojanic.  The reference
   * cited in that post was
   * <p>
   * Approximation Theory (C. Hastings, Jr., Note 143, Math. Tables Aids. Comp 6, 68 (1953))
   */

  public static double atan(double d)
  {
    if (d >= 1.0)
      return (0.5*Math.PI-d/(d*d+0.28));
    if (d <= -1.0)
      return (-0.5*Math.PI-d/(d*d+0.28));
    return (d/(1.0+0.28*d*d));
  }
}

public class CONVERTBITSPERSEC2MESHINDEX {
/**
     * We have a hard coded mesh.
     * 0-9999 = 0, 10000-
     *
     *
     * @param bitsPerSec -
     * @return - mesh index.
     */
    private int convertBitsPerSec2meshIndex(int bitsPerSec){

        if( bitsPerSec<0){
            return 0;
        }

        int bytesPerSec = bitsPerSec/1024;

        if( bytesPerSec<100){
            return bytesPerSec/10;
        }else if(bytesPerSec<500){
            return 10 + ((bytesPerSec-100)/50);
        }else if(bytesPerSec<5000){
            return 10 + 8 + ((bytesPerSec-500)/100);
        }

        //return max mesh index.
        return 10 + 8 + 45;
    }
}

public class CONVERTMESHINDEX2BITSPERSEC {
/**
     * The reverse of bit/sec -> mesh index calculation.
     * @param meshIndex - value between 0 and 70
     * @return lowest BitsPerSecond that meets that criteria.
     */
    private int convertMeshIndex2bitsPerSec(int meshIndex){

        int bytesPerSec=0;
        if(meshIndex<=0){
            return 0;
        }

        if(meshIndex<=10){
            bytesPerSec = meshIndex*10;
        }else if(meshIndex<=18){
            bytesPerSec = 100 + (meshIndex-10) * 50;
        }else{
            bytesPerSec = 500 + (meshIndex-18) * 100;
        }

        return bytesPerSec*1024;
    }
}

public class CALCULATEUNPINNEDSTEPSIZE {
/**
     * If setting is less then 100kBytes take 1 kByte steps.
     * If setting is less then 500kBytes take 5 kByte steps.
     * if setting is larger take 10 kBytes steps.
     * @param currLimitMax - current limit setting.
     * @return - set size for next change.
     */
    private int calculateUnpinnedStepSize(int currLimitMax){
        if(currLimitMax<102400){
            return 1024;
        }else if(currLimitMax<409600){
            return 1024*5;
        }else if(currLimitMax>=409600){
            return 1024*10;
        }
        return 1024;
    }
}

public class CALCULATEDOWNTICKMULTIPLE {
/**
     * Want to drop rate faster then increase.
     * @param c -
     * @return -
     */
    private float calculateDownTickMultiple(int c) {

        float multiple=0.0f;
        if(c<0){
            return multiple;
        }

        switch(c){
            case 0:
            case 1:
                multiple=0.25f;
                break;
            case 2:
                multiple=0.5f;
                break;
            case 3:
                multiple=1.0f;
                break;
            case 4:
                multiple=2.0f;
                break;
            case 5:
                multiple=3.0f;
                break;
            case 6:
                multiple=4.0f;
                break;
            case 7:
                multiple=6.0f;
                break;
            case 8:
                multiple=9.0f;
                break;
            case 9:
                multiple=15.0f;
                break;
            default:
                multiple=20.0f;
        }//switch
        return multiple;
    }
}

public class GETLIGHTERFONTWEIGHT {
/**
         * Returns a lighter font-weight.
         */
        public float getLighterFontWeight(float f) {
            // Round f to nearest 100...
            int weight = ((int)((f+50)/100))*100;
            switch (weight) {
            case 100: return 100;
            case 200: return 100;
            case 300: return 200;
            case 400: return 300;
            case 500: return 400;
            case 600: return 400;
            case 700: return 400;
            case 800: return 400;
            case 900: return 400;
            default:
                throw new IllegalArgumentException("Bad Font Weight: " + f);
            }
        }
}

