public class CONVERTSRGBTOLINEARRGB {
/**
     * Helper function to convert a color component in sRGB space to linear
     * RGB space.  Used to build a static lookup table.
     */
    private static int convertSRGBtoLinearRGB(int color) {

        // use of float and double arithmetic gives exactly same results
        float output;

        float input = color/255.0f;
        if (input <= 0.04045f) {
            output = input/12.92f;
        } else {
            output = (float) Math.pow((input + 0.055) / 1.055, 2.4);
        }
        int o = Math.round(output * 255.0f);

        return o;
    }
}

public class CONVERTLINEARRGBTOSRGB {
/** Helper function to convert a color component in linear RGB space to
      *  SRGB space. Used to build a static lookup table.
      */
    private static int convertLinearRGBtoSRGB(int color) {

         // use of float and double arithmetic gives exactly same results
        float output;

        float input = color/255.0f;

        if (input <= 0.0031308f) {
            output = input * 12.92f;
        } else {
            output = (1.055f * ((float) Math.pow(input, (1.0 / 2.4)))) - 0.055f;
        }

        int o = Math.round(output * 255.0f);

        return o;
    }
}

public class ARABICCHARTRANSPARENT {
/**
     * Returns true if the char is transparent.
     *
     * @param c The character to test.
     * @return True if the character is transparent, false otherwise.
     */
    public static boolean arabicCharTransparent(char c) {
        int charVal = c;
        if ((charVal  < 0x064B) || (charVal > 0x06ED))
            return false;

        if ((charVal <= 0x0655)                      ||
            (charVal == 0x0670)                      ||
            (charVal >= 0x06D6 && charVal <= 0x06E4) ||
            (charVal >= 0x06E7 && charVal <= 0x06E8) ||
            (charVal >= 0x06EA)) {
            return true;
        }
        return false;
    }
}

public class ARABICCHARSHAPESDUEL {
/**
     * Returns true if character has duel shaping.
     *
     * @param c The character to test.
     * @return True if the character is duel shaping, false otherwise.
     */
    private static boolean arabicCharShapesDuel(char c) {
        int charVal = c;

        if ((charVal == 0x0626)
         || (charVal == 0x0628)
         || (charVal >= 0x062A && charVal <= 0x062E)
         || (charVal >= 0x0633 && charVal <= 0x063A)
         || (charVal >= 0x0641 && charVal <= 0x0647)
         || (charVal >= 0x0649 && charVal <= 0x064A)
         || (charVal >= 0x0678 && charVal <= 0x0687)
         || (charVal >= 0x069A && charVal <= 0x06BF)
         || (charVal == 0x6C1)
         || (charVal == 0x6CC)
         || (charVal == 0x6CE)
         || (charVal >= 0x06D0 && charVal <= 0x06D1)
         || (charVal >= 0x06FA && charVal <= 0x06FC)) {
            return true;
        }
        return false;
    }
}

public class CHARSTARTSLIGATURE {
/**
     * Returns true if a ligature exists that starts with the
     * specified character.
     *
     * @param c The character to test.
     * @return True if there is a ligature that starts with c, false otherwise.
     */
    public static boolean charStartsLigature(char c) {
        int charVal = c;
        if (charVal == 0x064B || charVal == 0x064C || charVal == 0x064D
         || charVal == 0x064E || charVal == 0x064F || charVal == 0x0650
         || charVal == 0x0651 || charVal == 0x0652 || charVal == 0x0622
         || charVal == 0x0623 || charVal == 0x0625 || charVal == 0x0627) {
            return true;
        }
        return false;
    }
}

public class ISLIGATURE {
/**
     * Returns true if the glyph for the specified character
     * respresents a ligature.
     *
     * @param c The character to test.
     * @return True if c is a ligature, false otherwise.
     */
    public static boolean isLigature(char c) {
        int charVal = c;
        if ((charVal < 0xFE70) || (charVal > 0xFEFC))
            return false;

        if ((charVal <= 0xFE72)                      ||
            (charVal == 0xFE74)                      ||
            (charVal >= 0xFE76 && charVal <= 0xFE7F) ||
            (charVal >= 0xFEF5)) {
            return true;
        }
        return false;
    }
}

public class ISLATINCHAR {
/**
     * Returns true if the specified character is within one of the Latin
     * unicode character blocks.
     *
     * @param c The char to test.
     *
     * @return True if c is latin.
     */
    protected boolean isLatinChar(char c) {

        if ( c < 255 && Character.isLetterOrDigit( c )){
            // cheap quick check, should catch most lation-chars
            return true;
        }

        Character.UnicodeBlock block = Character.UnicodeBlock.of(c);

        if (block == Character.UnicodeBlock.BASIC_LATIN ||
            block == Character.UnicodeBlock.LATIN_1_SUPPLEMENT ||
            block == Character.UnicodeBlock.LATIN_EXTENDED_ADDITIONAL ||
            block == Character.UnicodeBlock.LATIN_EXTENDED_A ||
            block == Character.UnicodeBlock.LATIN_EXTENDED_B ||
            block == Character.UnicodeBlock.ARABIC ||
            block == Character.UnicodeBlock.ARABIC_PRESENTATION_FORMS_A ||
            block == Character.UnicodeBlock.ARABIC_PRESENTATION_FORMS_B) {
            return true;
        }
        return false;
    }
}

public class GETLIGHTERFONTWEIGHT {
/**
     * Returns a lighter font-weight.
     */
    public float getLighterFontWeight(float f) {
        // Round f to nearest 100...
        int weight = ((int)((f+50)/100))*100;
        switch (weight) {
        case 100: return 100;
        case 200: return 100;
        case 300: return 200;
        case 400: return 300;
        case 500: return 400;
        case 600: return 400;
        case 700: return 400;
        case 800: return 400;
        case 900: return 400;
        default:
            throw new IllegalArgumentException("Bad Font Weight: " + f);
        }
    }
}

public class GETBOLDERFONTWEIGHT {
/**
     * Returns a bolder font-weight.
     */
    public float getBolderFontWeight(float f) {
        // Round f to nearest 100...
        int weight = ((int)((f+50)/100))*100;
        switch (weight) {
        case 100: return 600;
        case 200: return 600;
        case 300: return 600;
        case 400: return 600;
        case 500: return 600;
        case 600: return 700;
        case 700: return 800;
        case 800: return 900;
        case 900: return 900;
        default:
            throw new IllegalArgumentException("Bad Font Weight: " + f);
        }
    }
}

public class ISXMLSPACE {
/**
     * Tests whether the given character is a valid space.
     */
    public static boolean isXMLSpace(char c) {
      return (c <= 0x0020) &&
             (((((1L << 0x0009) |
                 (1L << 0x000A) |
                 (1L << 0x000D) |
                 (1L << 0x0020)) >> c) & 1L) != 0);
    }
}

public class HYPOT {
/**
 * Returns sqrt(a^2 + b^2) without under/overflow.
 */
protected static double hypot(double a, double b) {
	double r;
	if (Math.abs(a) > Math.abs(b)) {
		r = b/a;
		r = Math.abs(a)*Math.sqrt(1+r*r);
	} else if (b != 0) {
		r = a/b;
		r = Math.abs(b)*Math.sqrt(1+r*r);
	} else {
		r = 0.0;
	}
	return r;
}
}

public class SIGN {
/**
Implements the FORTRAN sign (not sin) function.
See the code for details.
@param  a   a
@param  b   b
*/
private double sign(double a, double b) {
	if (b < 0.0) {
		return -Math.abs(a);
	} else {
		return Math.abs(a);      
	}
}
}

public class GEOMETRICPDF {
/**
 * Returns the probability distribution function of the discrete geometric distribution.
 * <p>
 * <tt>p(k) = p * (1-p)^k</tt> for <tt> k &gt;= 0</tt>.
 * <p>
 * @param k the argument to the probability distribution function.
 * @param p the parameter of the probability distribution function.
 */
public static double geometricPdf(int k, double p) {
	if (k<0) throw new IllegalArgumentException();
	return p * Math.pow(1-p,k);
}
}

public class BESSI1 {
/**
 * Modified Bessel Functions of First Kind - Order 1.
 */
public static double bessi1(double x) {
	double ax,ans;
	double y;

	if ((ax=Math.abs(x)) < 3.75) {
		y=x/3.75;
		y*=y;
		ans=ax*(0.5+y*(0.87890594+y*(0.51498869+y*(0.15084934
			+y*(0.2658733e-1+y*(0.301532e-2+y*0.32411e-3))))));
	}
	else {
		y=3.75/ax;
		ans=0.2282967e-1+y*(-0.2895312e-1+y*(0.1787654e-1
			-y*0.420059e-2));
		ans=0.39894228+y*(-0.3988024e-1+y*(-0.362018e-2
			+y*(0.163801e-2+y*(-0.1031555e-1+y*ans))));
		ans *= (Math.exp(ax)/Math.sqrt(ax));
		}
	return x < 0.0 ? -ans : ans;
 }
}

public class KURTOSIS {
/**
 * Returns the kurtosis (aka excess) of a data sequence.
 * @param moment4 the fourth central moment, which is <tt>moment(data,4,mean)</tt>.
 * @param standardDeviation the standardDeviation.
 */
public static double kurtosis(double moment4, double standardDeviation) {
	return -3 + moment4 / (standardDeviation * standardDeviation * standardDeviation * standardDeviation);
}
}

public class SAMPLEKURTOSIS {
/**
 * Returns the sample kurtosis (aka excess) of a data sequence.
 *
 * Ref: R.R. Sokal, F.J. Rohlf, Biometry: the principles and practice of statistics
 * in biological research (W.H. Freeman and Company, New York, 1998, 3rd edition)
 * p. 114-115.
 *
 * @param size the number of elements of the data sequence.
 * @param moment4 the fourth central moment, which is <tt>moment(data,4,mean)</tt>.
 * @param sampleVariance the <b>sample variance</b>.
 */
public static double sampleKurtosis(int size, double moment4, double sampleVariance) {
	 int    n=size;
	 double s2=sampleVariance; // (y-ymean)^2/(n-1)
	 double m4 = moment4*n;    // (y-ymean)^4
	 return m4*n*(n+1) / ((n-1)*(n-2)*(n-3)*s2*s2)
		  - 3.0*(n-1)*(n-1)/((n-2)*(n-3));
}
}

public class SAMPLEKURTOSISSTANDARDERROR {
/**
 * Return the standard error of the sample kurtosis.
 *
 * Ref: R.R. Sokal, F.J. Rohlf, Biometry: the principles and practice of statistics
 * in biological research (W.H. Freeman and Company, New York, 1998, 3rd edition)
 * p. 138.
 *
 * @param size the number of elements of the data sequence.
 */
public static double sampleKurtosisStandardError(int size) {
	 int n=size;
	 return Math.sqrt( 24.0*n*(n-1)*(n-1)/((n-3)*(n-2)*(n+3)*(n+5)) );
}
}

public class SAMPLESKEW {
/**
 * Returns the sample skew of a data sequence.
 *
 * Ref: R.R. Sokal, F.J. Rohlf, Biometry: the principles and practice of statistics
 * in biological research (W.H. Freeman and Company, New York, 1998, 3rd edition)
 * p. 114-115.
 *
 * @param size the number of elements of the data sequence.
 * @param moment3 the third central moment, which is <tt>moment(data,3,mean)</tt>.
 * @param sampleVariance the <b>sample variance</b>.
 */
public static double sampleSkew(int size, double moment3, double sampleVariance) {
	 int    n=size;
	 double s=Math.sqrt(sampleVariance); // sqrt( (y-ymean)^2/(n-1) )
	 double m3 = moment3*n;    // (y-ymean)^3
	 return n*m3 / ((n-1)*(n-2)*s*s*s);
}
}

public class SAMPLESKEWSTANDARDERROR {
/**
 * Return the standard error of the sample skew.
 *
 * Ref: R.R. Sokal, F.J. Rohlf, Biometry: the principles and practice of statistics
 * in biological research (W.H. Freeman and Company, New York, 1998, 3rd edition)
 * p. 138.
 *
 * @param size the number of elements of the data sequence.
 */
public static double sampleSkewStandardError(int size) {
	 int n=size;
	 return Math.sqrt( 6.0*n*(n-1)/((n-2)*(n+1)*(n+3)) );
}
}

public class SAMPLEVARIANCE {
/**
 * Returns the sample variance of a data sequence.
 * That is <tt>(sumOfSquares - mean*sum) / (size - 1)</tt> with <tt>mean = sum/size</tt>.
 *
 * @param size the number of elements of the data sequence. 
 * @param sum <tt>== Sum( data[i] )</tt>.
 * @param sumOfSquares <tt>== Sum( data[i]*data[i] )</tt>.
 */
public static double sampleVariance(int size, double sum, double sumOfSquares) {
	double mean = sum / size;
	return (sumOfSquares - mean*sum) / (size - 1);
}
}

public class SAMPLEWEIGHTEDVARIANCE {
/**
 * Returns the sample weighted variance of a data sequence.
 * That is <tt>(sumOfSquaredProducts  -  sumOfProducts * sumOfProducts / sumOfWeights) / (sumOfWeights - 1)</tt>.
 *
 * @param sumOfWeights <tt>== Sum( weights[i] )</tt>. 
 * @param sumOfProducts <tt>== Sum( data[i] * weights[i] )</tt>.
 * @param sumOfSquaredProducts <tt>== Sum( data[i] * data[i] * weights[i] )</tt>.
 */
public static double sampleWeightedVariance(double sumOfWeights, double sumOfProducts, double sumOfSquaredProducts) {
	return (sumOfSquaredProducts  -  sumOfProducts * sumOfProducts / sumOfWeights) / (sumOfWeights - 1);
}
}

public class VARIANCE {
/**
 * Returns the variance of a data sequence.
 * That is <tt>(sumOfSquares - mean*sum) / size</tt> with <tt>mean = sum/size</tt>.
 *
 * @param size the number of elements of the data sequence. 
 * @param sum <tt>== Sum( data[i] )</tt>.
 * @param sumOfSquares <tt>== Sum( data[i]*data[i] )</tt>.
 */
public static double variance(int size, double sum, double sumOfSquares) {
	double mean = sum / size;
	return (sumOfSquares - mean*sum) / size;
}
}

public class EPSILONCEILING {
/**
 * Similar to Math.ceil(value), but adjusts small numerical rounding errors +- epsilon.
 */
public static long epsilonCeiling(double value) {
	double epsilon = 0.0000001;
	return (long) Math.ceil(value - epsilon);
}
}

