public class COLORDISTANCE {
/**
	 * 	Simple Color Distance.
	 * 	(3d point distance)
	 *	@param r1 first red
	 *	@param g1 first green
	 *	@param b1 first blue
	 *	@param r2 second red
	 *	@param g2 second green
	 *	@param b2 second blue
	 *	@return 3d distance for relative comparison
	 */
	public static double colorDistance (double r1, double g1, double b1,
          double r2, double g2, double b2)
	{
		double a = (r2 - r1) + 0.1;
		double b = (g2 - g1) + 0.1;
		double c = (b2 - b1) + 0.1;
		return Math.sqrt (a*a + b*b + c*c);
	}
}

public class FINISHSCORE {
/**
     * <p>
     * Calculate the final score as a percentage, given the highest possible
     * score and the actual score achieved.
     * </p>
     */
    public static double finishScore(double allCorrect, double actual)
    {
        if ( actual < 0.0D ) { return 0.0D; }
        else { return (100D * actual) / allCorrect; }
    }
}

