public class DETERMINEUNSIGNEDBITSIZE {
/**
     * Determine the minimum number of bits required to hold the given
     * unsigned value (may be zero)
     */
    public static int determineUnsignedBitSize( long value )
    {
        //--This is probably a really bad way of doing this...
        int  topBit = 32;
        long mask = 0x80000000L;

        while( topBit > 0 )
        {
            if( (value & mask) != 0 ) return topBit;

            mask >>= 1;
            topBit--;
        }

        return 0;
    }
}

public class CONVERTSRGBTOLINEARRGB {
/** Helper function to convert a color component in sRGB space to linear
     * RGB space.  Used to build a static lookup table.
     */
    private static int convertSRGBtoLinearRGB(int color) {

        float input, output;

        input = ((float) color) / 255.0f;
        if (input <= 0.04045f) {
            output = input / 12.92f;
        }
        else {
            output = (float) Math.pow((input + 0.055) / 1.055, 2.4);
        }
        int o = Math.round(output * 255.0f);

        return o;
    }
}

public class CONVERTLINEARRGBTOSRGB {
/** Helper function to convert a color component in linear RGB space to
      *  SRGB space. Used to build a static lookup table.
      */
    private static int convertLinearRGBtoSRGB(int color) {

        float input, output;

        input = ((float) color) / 255.0f;

        if (input <= 0.0031308) {
            output = input * 12.92f;
        }
        else {
            output = (1.055f *
                ((float) Math.pow(input, (1.0 / 2.4)))) - 0.055f;
        }

        int o = Math.round(output * 255.0f);

        return o;
    }
}

