public class ISXMLVALIDCHARACTER {
/**
	 * Determines whether the character is valid in XML. Invalid characters
	 * include most of the range x00-x1F, and more. 
	 * @see http://www.w3.org/TR/2000/REC-xml-20001006#NT-Char.
	 */
	public static boolean isXMLValidCharacter(char character) {
		// Order the tests in such a sequence that the most probable
		// conditions are tested first.
		return character >= 0x20 && character <= 0xD7FF || character == 0x9
				|| character == 0xA || character == 0xD
				|| character >= 0xE000 && character <= 0xFFFD
				|| character >= 0x10000 && character <= 0x10FFFF;
	}
}

public class MODULE {
/**
     * This function returns the signal represented by an int
     */
    private int module(int number) {
        if (number > 0)
            return 1;
        else if (number < 0)
            return -1;
        else
            return 0;
    }
}

public class XTOTILEX {
/**
  * Converts a pixel's X coordinate into a horizontal tile index
  * relative to a given tile grid layout specified by its X offset
  * and tile width.
  */
 public static int XToTileX(int x, int tileGridXOffset, int tileWidth) {
     x -= tileGridXOffset;
     if (x < 0) {
         x += 1 - tileWidth; // Force round to -infinity
     }
     return x/tileWidth;
 }
}

public class YTOTILEY {
/**
  * Converts a pixel's Y coordinate into a vertical tile index
  * relative to a given tile grid layout specified by its Y offset
  * and tile height.
  */
 public static int YToTileY(int y, int tileGridYOffset, int tileHeight) {
     y -= tileGridYOffset;
     if (y < 0) {
         y += 1 - tileHeight; // Force round to -infinity
     }
     return y/tileHeight;
 }
}

public class COMPARE {
/**
     * Compares two {@code double} values. This method is similar to
     * {@link Double#compare(double,double)} except that it also order
     * NaN values.
     */
    private static int compare(final double v1, final double v2) {
        if (Double.isNaN(v1) && Double.isNaN(v2)) {
            final long bits1  = Double.doubleToRawLongBits(v1);
            final long bits2  = Double.doubleToRawLongBits(v2);
            if (bits1 < bits2) return -1;
            if (bits1 > bits2) return +1;
        }
        return Double.compare(v1, v2);
    }
}

public class CORRECTPOI {
/**
     * Corrects POI's Cp1252 output.  There's a bug somewhere in POI that
     * makes it produce incorrect characters.  Not sure where and don't have
     * time to track it down.  But I have visually checked the input 
     * documents to verify that Doc is producing the right character, and
     * that POI is not.
     * 
     * @param ch  the POI-produced character to check
     * @return    the corrected character
     */
    private static int correctPOI(int ch) {
        switch (ch) {
            case 8734:
                // POI produced the infinity sign when it should have 
                // produced the degrees sign.
                return 176;
            case 214:
                // POI produced an umat O instead of an ellipses mark.
                return 8230;
            case 237:
                // POI produced an acute i instead of a fancy single quote
                return 8217;
            case 236:
                // POI produced a reverse acute i instead of fancy double quote
                return 8220;
            case 238:
                // POI produced a caret i instead of fancy double quote
                return 8221;
            default:
                return ch;
        }
    }
}

public class GETHEXVALUE {
/**
     * returns hex value of a hex character, or 16 if not a hex character
     */
    static int getHexValue(int c) {

        if (c >= '0' && c <= '9') {
            c -= '0';
        } else if (c > 'z') {
            c = 16;
        } else if (c >= 'a') {
            c -= ('a' - 10);
        } else if (c > 'Z') {
            c = 16;
        } else if (c >= 'A') {
            c -= ('A' - 10);
        } else {
            c = -1;
        }

        return c;
    }
}

