public class SGN {
/**
     * Extracts the leading sign of x.
     * 
     * @param x Any double value.
     * @return If x has a positive value <code>-1.0</code>, for <code>x = 0.0</code>
     * here comes <code>0.0</code> and if x has a negative the method returns 
     * <code>-1.0</code>.
     */
	public static double sgn(double x){
	    if( x < 0.0 ) {
		return -1.0;
	    }
	    else if( x > 0.0 ){
		return 1.0;
	    }
	    else {
		return 0.0;
	    }               
	}
}

public class FA {
/**
     * calculates the attractive forces
     */
    protected double fa(double x, double k) {
        double force = (x * x / k);
        return force;
    }
}

public class FR {
/**
     * calculates the repulsive forces
     */
    protected double fr(double x, double k) {
        double force = (k * k) / x;
        return force;
    }
}

public class CONVERT {
/**
     * converts a long to the nearest int value
     */
    private static int convert(long input)
    {

        int result;

        if (input > Integer.MAX_VALUE)
        {
            result = Integer.MAX_VALUE;
        }
        else if (input < Integer.MIN_VALUE)
        {
            result = Integer.MIN_VALUE;
        }
        else
        {
            result = (int) input;
        }

        return result;
    }
}

public class ISIDLALPHABETICCHAR {
/**
     * True if character is one of 114 Alphabetic characters as
     * specified in Table 2 of Chapter 3 in CORBA spec.
     */
    private static boolean isIDLAlphabeticChar(char c) {

        // NOTE that we can't use the java.lang.Character
        // isUpperCase, isLowerCase, etc. methods since they
        // include many characters other than the Alphabetic list in
        // the CORBA spec.  Instead, we test for inclusion in the
        // Unicode value ranges for the corresponding legal characters.

        boolean alphaChar =
            (
             // A - Z
             ((c >= 0x0041) && (c <= 0x005A))

             ||

             // a - z
             ((c >= 0x0061) && (c <= 0x007A))

             ||

             // other letter uppercase, other letter lowercase, which is
             // the entire upper half of C1 Controls except X and /
             ((c >= 0x00C0) && (c <= 0x00FF)
              && (c != 0x00D7) && (c != 0x00F7)));

        return alphaChar;
    }
}

public class ABSDELTA {
/**
   * Compute the absolute value of the difference between two floating-point
   * numbers having single precision.
   * @return the absolute value of the difference between two floats.
   **/
  public static float absDelta (float f1, float f2)
  {
    double delta = f1 - f2;
    return (float)((delta < 0) ? delta * -1.0 : delta);
  }
}

public class INVALIDCHAR {
/** Return true if ch is invalid as a character in an
    * identifier.  If ch is a number, it is invalid only if
    * isFirst is true.
    */
    private boolean invalidChar( char ch, boolean isFirst )
    {
        if (('A'<=ch) && (ch<='Z'))
            return false ;
        else if (('a'<=ch) && (ch<='z'))
            return false ;
        else if (('0'<=ch) && (ch<='9'))
            return isFirst ;
        else if (ch=='%')
            return false ;
        else if (ch=='$')
            return false ;
        else if (ch=='_')
            return false ;
        else
            return true ;
    }
}

public class PARSECACHENUMPAGESPROPERTY {
/** Possibly override page cache size with user-specified property */
  protected int parseCacheNumPagesProperty(int defaultNum) {
    String cacheNumPagesString = System.getProperty("cacheNumPages");
    if (cacheNumPagesString != null) {
      try {
        return Integer.parseInt(cacheNumPagesString);
      } catch (Exception e) {
        System.err.println("Error parsing cacheNumPages property:");
        e.printStackTrace();
      }
    }
    return defaultNum;
  }
}

public class UNSIGNEDBYTE {
/** Returns a big-endian unsigned representation of the int. */
        long unsignedByte(int arg) {
            long val;
            if (arg >= 0) {
                val = arg;
            } else {
                val = (long)(((long)unsignedByte((short)(arg >>> 16)) << 16) |
                             ((short)arg));
            }
            return val;
        }
}

